import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('Component Composition', () => {
  test('Card component renders with className "card"', async () => {
    const { container: root } = render(<App />);
    const card = root.querySelector('.card');
if (!card) throw new Error('No element with class "card" found');
  });

  test('Card has header with title "Notifications"', async () => {
    const { container: root } = render(<App />);
    const header = root.querySelector('.card-header');
if (!header) throw new Error('No .card-header found');
if (!header.textContent.includes('Notifications'))
  throw new Error('Card header should contain "Notifications"');
  });

  test('Card has a body section', async () => {
    const { container: root } = render(<App />);
    const body = root.querySelector('.card-body');
if (!body) throw new Error('No .card-body found');
  });

  test('Two Alert components rendered inside Card', async () => {
    const { container: root } = render(<App />);
    const body = root.querySelector('.card-body');
const alerts = body.querySelectorAll('.alert');
if (alerts.length !== 2) throw new Error('Expected 2 alerts inside card body, found ' + alerts.length);
  });

  test('Alerts have correct type classes', async () => {
    const { container: root } = render(<App />);
    const success = root.querySelector('.alert-success');
if (!success) throw new Error('No .alert-success found');
if (!success.textContent.includes('Task completed!'))
  throw new Error('Success alert should contain "Task completed!"');
const warning = root.querySelector('.alert-warning');
if (!warning) throw new Error('No .alert-warning found');
if (!warning.textContent.includes('Low disk space'))
  throw new Error('Warning alert should contain "Low disk space"');
  });
});
